sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_GetStoreAppStatus(aStoreAppWhitelist,vExpected)
	{
		function TestCase_GetStoreAppStatus_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected === false)
			{
				return (vResult === false);
			}

			if (vExpected == 'all')
			{
				return (vResult.length > 500);
			}

			var nExpected = x_snc_devtools.GetIntegerValue(vExpected);
			if (vResult.length != nExpected)
			{
				return false;
			}

			return true;
		}
		
		test.TestCase(
			'Function GetStoreAppStatus()',
			GetStoreAppStatus,
			{
				'aStoreAppWhitelist': aStoreAppWhitelist
			},
			vExpected,
			TestCase_GetStoreAppStatus_CheckResult);
	}
		
	TestCase_GetStoreAppStatus(null,false);
	TestCase_GetStoreAppStatus([],false);

	var aWhitelistSysIds = [];
	var aWhitelistScopes = [];
	var aWhitelistNames = [];
	var aWhitelistMixed = [];

	var grStoreApp = new GlideRecord('sys_store_app');
	grStoreApp.setLimit(5);
	grStoreApp.query();
	var nMixed = 0;
	while (grStoreApp.next())
	{
		aWhitelistSysIds.push(x_snc_devtools.GetStringValue(grStoreApp.sys_id));
		aWhitelistScopes.push(x_snc_devtools.GetStringValue(grStoreApp.scope));
		aWhitelistNames.push(x_snc_devtools.GetStringValue(grStoreApp.name));

		if (nMixed == 0)
		{
			aWhitelistMixed.push(x_snc_devtools.GetStringValue(grStoreApp.sys_id));
		}
		else if (nMixed == 1)
		{
			aWhitelistMixed.push(x_snc_devtools.GetStringValue(grStoreApp.scope));
		}
		else if (nMixed == 2)
		{
			aWhitelistMixed.push(x_snc_devtools.GetStringValue(grStoreApp.name));
		}		

		nMixed++;
		if (nMixed == 3)
		{
			nMixed = 0;
		}
	}

	TestCase_GetStoreAppStatus(aWhitelistSysIds,5);
	TestCase_GetStoreAppStatus(aWhitelistScopes,5);
	TestCase_GetStoreAppStatus(aWhitelistNames,5);
	TestCase_GetStoreAppStatus(aWhitelistMixed,5);

	//TestCase_GetStoreAppStatus(['all'],'all');
	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
